/**
 * SceneBlockedReason says why PlayService refused a scene call with
 * `failed_precondition`.
 *
 * @generated from enum meurpg.play.v1.SceneBlockedReason
 */
export enum SceneBlockedReason {
  /**
   * @generated from enum value: SCENE_BLOCKED_REASON_UNSPECIFIED = 0;
   */
  UNSPECIFIED = 0,

  /**
   * Unused: it was OpenScene's refusal of a point with no actions in Etapa
   * 7. Since Etapa 8 (question 63) any SCENE point opens, even with no
   * actions, so the server never sends it. The value stays so the numbers
   * do not change.
   *
   * @generated from enum value: SCENE_BLOCKED_REASON_NO_ACTIONS = 1;
   */
  NO_ACTIONS = 1,

  /**
   * RollSceneCheck: no scene is open in the session, or it is not the one
   * the action belongs to. PutOnStage: no scene is open, so there is no
   * stage.
   *
   * @generated from enum value: SCENE_BLOCKED_REASON_NO_OPEN_SCENE = 2;
   */
  NO_OPEN_SCENE = 2,

  /**
   * RollSceneCheck: the character has no attempt left at this action while
   * the scene has been open: it rolled as many times as the action's
   * `max_attempts` allows, plus the attempts the master granted
   * (GrantSceneAttempt). The master may grant one more, raise the limit, or
   * close and open the scene again, which resets every count. An unlimited
   * action stops at 200 rolls per character in one opening, with this same
   * reason. The name stays from the time the limit was one roll ("already
   * rolled"); the reason is the same.
   *
   * @generated from enum value: SCENE_BLOCKED_REASON_ALREADY_ROLLED = 3;
   */
  ALREADY_ROLLED = 3,

  /**
   * RollSceneCheck: the campaign's dice setting does not allow this way of
   * rolling (RN-18): the app's roll when everybody rolls real dice, a typed
   * result when everybody rolls in the app.
   *
   * @generated from enum value: SCENE_BLOCKED_REASON_WRONG_DICE_MODE = 4;
   */
  WRONG_DICE_MODE = 4,

  /**
   * RollSceneCheck: the caller has no living character in the campaign to
   * roll for.
   *
   * @generated from enum value: SCENE_BLOCKED_REASON_NO_CHARACTER = 5;
   */
  NO_CHARACTER = 5,

  /**
   * PutOnStage: 4 NPCs are on the stage already (the limit, MR-031).
   *
   * @generated from enum value: SCENE_BLOCKED_REASON_STAGE_FULL = 6;
   */
  STAGE_FULL = 6,
}

/**
 * Describes the enum meurpg.play.v1.SceneBlockedReason.
 */
export const SceneBlockedReasonSchema: GenEnum<SceneBlockedReason> = /*@__PURE__*/
  enumDesc(file_meurpg_play_v1_scene, 0);

